'use strict';
(()=>{
 const numeric=[['belt-torque','outputTorque'],['belt-preload','pretension'],['belt-width','width']];
 window.renderBeltReview=()=>{const c=beltDesign,a=beltAnalysis();$('belt-enable').checked=c.enabled;$('belt-mount-compare').textContent=c.revisedMount?'초기 사각판 간섭 비교':'Ø200 개선판 복원';$('belt-cover').checked=c.cover;for(const[id,key]of numeric)$(id).value=c[key];$('belt-yaw').value=mechanism.angles[4];$('belt-yaw-out').textContent=mechanism.angles[4]+'°';
  const map=p=>[170+p[0]*1.15,185-p[1]*1.15],path=a.path.map(map).map((p,i)=>(i?'L':'M')+p.join(' ')).join(' ')+'Z';$('belt-plan').innerHTML=`<path d="${path}" fill="none" stroke="#334b3b" stroke-width="7"/>`+a.circles.map(p=>{const xy=map([p.x,p.y]);return`<circle cx="${xy[0]}" cy="${xy[1]}" r="${p.r*1.15}" fill="#d1dcc9" stroke="#6f8766" stroke-width="2"/><circle cx="${xy[0]}" cy="${xy[1]}" r="${p.id==='output'?60*1.15:15*1.15}" fill="#f1f4eb"/><text x="${xy[0]}" y="${xy[1]+p.r*1.15+20}" text-anchor="middle" fill="#425d3b" font-size="11">${{output:'요축 출력',drive:'모터축 후보',idler:'장력 아이들러 후보'}[p.id]} · ${p.teeth}T</text>`;}).join('')+`<text x="20" y="28" fill="#5e7853" font-size="12">+X 전방 → / +Y 로봇 좌측 ↑ / 벨트 평면 Z${c.z} mm</text>`;
  $('belt-results').innerHTML=[['감속비 / 피치원 지름',`${a.ratio.toFixed(3)} : 1 / 출력 Ø${a.outputDiameter.toFixed(1)} mm`],['명목 벨트 / 아이들러 조정',`${a.beltTeeth}T × ${c.pitch} = ${a.nominalLength} mm / ${a.idlerOffset.toFixed(2)} mm`],['작은 풀리 감김 / 맞물림',`${a.driveWrap.toFixed(1)}° / ${a.engagedDriveTeeth.toFixed(1)} teeth`],['출력 검토 토크 / 풀리 입력축',`${a.designTorque.toFixed(1)} / ${a.inputTorque.toFixed(1)} N·m`],['상위 20:1·효율85% 가정 모터축',`${a.motorTorque.toFixed(2)} N·m / 정격·열 선정값 아님`],['장력 차 / 팽팽·느슨한 측',`${a.difference.toFixed(0)} / ${a.tight.toFixed(0)} · ${a.slack.toFixed(0)} N`],['풀리 축 횡하중 상한 가정',`${a.radialBound.toFixed(0)} N / 두 장력의 벡터합 상한`],['Ø30 축 등가 응력',`${a.combined.toFixed(1)} MPa / 굽힘+비틀림 가정`]].map(([k,v])=>`<tr><td>${k}</td><td>${v}</td></tr>`).join('');
  $('belt-status').textContent=(a.positiveSlack?'느슨한 측 장력은 양수입니다. ':'예압 부족: 느슨한 측 장력이 0 이하입니다. ')+(a.takeupPossible?'±6 mm 슬롯 안에서 정수 잇수의 길이를 맞춥니다. ':'선정 벨트 길이가 슬롯 범위를 벗어납니다. ')+(c.enabled?'현재 5축 순서: 기초 J5 요 → J1·J2·J3 피치 → J4 롤.':'기존 비교안: J1·J2·J3 피치 → J4 롤 → 상단 J5 요.');$('belt-status').classList.toggle('warn',!a.positiveSlack||!a.takeupPossible);
  const gaps=beltBayClearances();$('belt-bay-status').textContent=gaps.map(r=>(r.side>0?'좌측':'우측')+' 팩 ↔ '+r.part+' 분리축 여유 '+r.gap.toFixed(1)+' mm'+(r.gap<0?' / 예약 공간 중첩':'')).join(' · ')+' · 현재 요각의 직육면체 예약 검사이며 공차·전체 이동부 검증이 아닙니다.';$('belt-bay-status').classList.toggle('warn',gaps.some(r=>r.gap<0));
 };
 function refresh(){window.renderMechanismReview();inspector();checkClearance();draw();}
 $('belt-mount-compare').onclick=()=>{beltDesign.revisedMount=!beltDesign.revisedMount;mechanism.angles[4]=45;refresh();};
 $('belt-enable').onchange=()=>{beltDesign.enabled=$('belt-enable').checked;refresh();};$('belt-cover').onchange=()=>{beltDesign.cover=$('belt-cover').checked;draw();};
 for(const[id,key]of numeric)$(id).oninput=()=>{const el=$(id),v=+el.value;if(el.value!==''&&Number.isFinite(v)&&v>=+el.min&&v<=+el.max){beltDesign[key]=v;refresh();}};
 $('belt-yaw').oninput=()=>{mechanism.angles[4]=+$('belt-yaw').value;refresh();};
 $('belt-focus').onclick=()=>{mechanism.scope='base';partGroup='base';document.querySelectorAll('[data-group]').forEach(b=>b.classList.toggle('active',b.dataset.group==='base'));select('belt');setView('iso');zoom=1;draw();$('model').scrollIntoView({block:'center'});};
 window.renderBeltReview();select(rideDesign.bogie?'bogie':'belt');
})();
